/***
 * MARK: runnerSlots
 * @description Single source of truth for "what is this Runner doing" across
 * every fleet surface. One Runner executes at most one task at a time; the
 * backend fence (`RUNNER_BUSY`) enforces it, and these helpers render it:
 * live assignments group into exactly one slot per Runner (the current
 * task), so two tasks can never render as live under one Runner. A group
 * carrying extras is a converging backend violation — surfaces flag it,
 * never render it as parallel live work.
 * @example groupLiveAssignments([{ runnerId: 'r1', taskId: 't1' }])
 ***/

/***
 * MARK: groupLiveAssignments
 * @description Groups live assignments into one slot per Runner. The current
 * task is the group's first row (claim order); when the monitor's
 * `runnerLoad` names a different current task it wins (server truth). Rows
 * without a Runner id are dropped; a missing/empty input yields no slots.
 * @example groupLiveAssignments([{ runnerId: 'r1', taskId: 't1' }], null)
 * @param {Array<Object>} [assignments] - `liveAssignments` rows.
 * @param {Array<Object>|null} [runnerLoad] - `runnerLoad` rows (or null).
 * @returns {Array<{runnerId: string, current: Object|null, extras: Array<Object>, liveHoldCount: number}>}
 ***/
export const groupLiveAssignments = (assignments, runnerLoad = null) => {
  const groups = new Map();
  for (const row of Array.isArray(assignments) ? assignments : []) {
    if (!row || typeof row.runnerId !== 'string' || !row.runnerId) continue;
    const group = groups.get(row.runnerId) || { runnerId: row.runnerId, rows: [] };
    group.rows.push(row);
    groups.set(row.runnerId, group);
  }
  const loadByRunner = new Map();
  for (const row of Array.isArray(runnerLoad) ? runnerLoad : []) {
    if (!row || typeof row.runnerId !== 'string' || !row.runnerId) continue;
    if (!loadByRunner.has(row.runnerId)) loadByRunner.set(row.runnerId, row);
  }
  return [...groups.values()].map((group) => {
    const server = loadByRunner.get(group.runnerId) || null;
    let rows = group.rows;
    if (server != null && server.currentTaskId != null && server.currentTaskId !== '') {
      const at = rows.findIndex((r) => String(r.taskId) === String(server.currentTaskId));
      if (at > 0) rows = [rows[at], ...rows.slice(0, at), ...rows.slice(at + 1)];
    }
    const serverCount = Number(server?.liveHoldCount);
    return {
      runnerId: group.runnerId,
      current: rows[0] || null,
      extras: rows.slice(1),
      liveHoldCount:
        Number.isFinite(serverCount) && serverCount > 0 ? serverCount : rows.length,
    };
  });
};

/***
 * MARK: MEMORY_LOW_MB
 * @description Free-memory floor behind the fleet UI's pressure note: a
 * Runner reporting less free RAM than this renders an amber warning.
 * Display-only — it never gates dispatch.
 * @example MEMORY_LOW_MB => 512
 ***/
export const MEMORY_LOW_MB = 512;

/***
 * MARK: describeMemoryPressure
 * @description Best-effort memory posture from heartbeat facts. Old Runners
 * (no `memoryFreeMb` fact) and unmeasurable values read as null — the UI
 * shows nothing rather than a fabricated number.
 * @example describeMemoryPressure({ memoryFreeMb: 128 }) => { freeMb: 128, low: true }
 * @param {Object|null} [facts] - Runner heartbeat facts.
 * @returns {{freeMb: number, low: boolean}|null}
 ***/
export const describeMemoryPressure = (facts) => {
  const mb = facts?.memoryFreeMb;
  if (typeof mb !== 'number' || !Number.isFinite(mb) || mb < 0) return null;
  return { freeMb: mb, low: mb < MEMORY_LOW_MB };
};

/***
 * MARK: formatMemoryMb
 * @description Human short form for a free-memory reading: megabytes below
 * 1 GiB, one-decimal gigabytes above.
 * @example formatMemoryMb(2048) => '2.0 GB free'
 * @param {number} mb - Free megabytes.
 * @returns {string}
 ***/
export const formatMemoryMb = (mb) => {
  if (typeof mb !== 'number' || !Number.isFinite(mb) || mb < 0) return '—';
  if (mb < 1024) return `${Math.floor(mb)} MB free`;
  return `${(mb / 1024).toFixed(1)} GB free`;
};

import { useEffect, useMemo, useState } from 'react';

import { api } from '../../../services/api';
import { MarkdownViewer } from '../../common/MarkdownViewer';
import { formatTaskTitleFirstLine } from '../../tasks/taskFormatters';
import {
  describeMemoryPressure,
  formatMemoryMb,
  groupLiveAssignments,
} from './runnerSlots';

/***
 * MARK: formatRunnerElapsed
 * @description mm:ss elapsed from an ISO start timestamp against now.
 *   Missing/unparseable starts render as an em dash — never invented.
 * @example formatRunnerElapsed('2026-10-27T12:00:00.000Z', Date.parse('2026-10-27T12:01:30.000Z')) => '01:30'
 ***/
export const formatRunnerElapsed = (startedAt, nowMs) => {
  const start = Date.parse(startedAt || '');
  if (!Number.isFinite(start) || !Number.isFinite(nowMs) || nowMs < start) return '—';
  const totalSeconds = Math.floor((nowMs - start) / 1000);
  const mins = Math.floor(totalSeconds / 60);
  const secs = totalSeconds % 60;
  return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
};

const escapeRegExp = (value) => String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/***
 * MARK: runnerFreshness
 * @description Heartbeat freshness for the status dot: a Runner heartbeats
 *   every 15s, so anything seen within 60s counts as live. Unknown stays
 *   unknown (grey) rather than alarming.
 * @example runnerFreshness(new Date().toISOString(), Date.now()) => 'live'
 ***/
export const runnerFreshness = (lastSeenAt, nowMs) => {
  const seen = Date.parse(lastSeenAt || '');
  if (!Number.isFinite(seen)) return 'unknown';
  return nowMs - seen <= 60000 ? 'live' : 'stale';
};

const FRESHNESS_DOT = {
  live: 'bg-emerald-400 animate-pulse',
  stale: 'bg-amber-400',
  unknown: 'bg-slate-500',
};

/***
 * MARK: useRunnerMonitor
 * @description Polls the Runner fleet monitor (`GET /runners/monitor`) plus
 *   the registry list (`GET /runners`) for harness capabilities. Shared by
 *   the desktop per-runner widget and the compact mobile rows so both show
 *   the same fleet picture.
 * @example const { assignments, registry } = useRunnerMonitor({ pollMs: 5000 });
 ***/
export const useRunnerMonitor = ({ pollMs = 5000 } = {}) => {
  const [monitor, setMonitor] = useState(null);
  const [runners, setRunners] = useState(null);

  useEffect(() => {
    let mounted = true;
    let timer = null;
    const load = async () => {
      try {
        const [m, list] = await Promise.all([
          api.getRunnerMonitor().catch(() => null),
          api.getRunners().catch(() => null),
        ]);
        if (!mounted) return;
        if (m) setMonitor(m);
        if (Array.isArray(list)) setRunners(list);
      } catch {
        // Best-effort: stale cards stay until the next poll succeeds.
      }
    };
    void load();
    timer = setInterval(() => void load(), pollMs);
    return () => {
      mounted = false;
      if (timer) clearInterval(timer);
    };
  }, [pollMs]);

  return useMemo(() => {
    const assignments = Array.isArray(monitor?.liveAssignments)
      ? monitor.liveAssignments.filter((a) => a && a.runnerId)
      : [];
    const registry = new Map(
      (Array.isArray(runners) ? runners : [])
        .filter((r) => r && r.runnerId)
        .map((r) => [r.runnerId, r]),
    );
    return {
      assignments,
      registry,
      runnerLoad: Array.isArray(monitor?.runnerLoad) ? monitor.runnerLoad : null,
      scheduler: monitor?.scheduler || null,
    };
  }, [monitor, runners]);
};

const taskTitle = (task) => {
  const title = formatTaskTitleFirstLine(task?.title || task?.goal || '', '');
  return (typeof title === 'string' && title.trim()) || '(untitled task)';
};

const runnerLogTail = (task, runnerId, limit = 6) => {
  const entries = Array.isArray(task?.logEntries) ? task.logEntries : [];
  const mine = entries.filter((e) => {
    if (!e) return false;
    if (e.meta?.runnerId) return e.meta.runnerId === runnerId;
    if (typeof e.text !== 'string') return false;
    // eslint-disable-next-line security/detect-non-literal-regexp -- runnerId is escapeRegExp-quoted above
    return new RegExp(`^\\[runner\\s+${escapeRegExp(runnerId)}\\]`, 'i').test(e.text);
  });
  return mine.slice(-limit);
};

/***
 * MARK: PerRunnerTasksWidget
 * @description One card per busy Runner (never one card per assignment):
 *   which Runner runs which single task, on what stage, and for how long.
 *   Assignments group through `groupLiveAssignments`, so a Runner holding
 *   two leases (a converging backend violation the fence normally forbids)
 *   renders one current-task slot plus a warning — never two live cards.
 *   Full variant (desktop default) shows the task goal, stage/epoch pills,
 *   harness capabilities, freshness, memory posture, and a runner log tail.
 *   Compact variant (crowded screens, mobile) collapses each Runner to one
 *   row with an expandable tail.
 * @example <PerRunnerTasksWidget tasks={tasks} compact={false} />
 ***/
export function PerRunnerTasksWidget({ tasks = [], stages = [], compact = false, pollMs = 5000 }) {
  const { assignments, registry, runnerLoad } = useRunnerMonitor({ pollMs });
  const [nowMs, setNowMs] = useState(() => Date.now());

  useEffect(() => {
    if (assignments.length === 0) return;
    const timer = setInterval(() => setNowMs(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [assignments.length]);

  const taskById = useMemo(() => {
    const map = new Map();
    for (const t of Array.isArray(tasks) ? tasks : []) {
      if (t && t.id != null) map.set(String(t.id), t);
    }
    return map;
  }, [tasks]);

  const stageById = useMemo(() => {
    const map = new Map();
    for (const s of Array.isArray(stages) ? stages : []) {
      if (s && s.id != null) map.set(String(s.id), s);
    }
    return map;
  }, [stages]);

  const stageName = (stageId) => {
    if (stageId == null || stageId === '') return '…';
    const stage = stageById.get(String(stageId));
    const name = stage?.name || stage?.title;
    return (typeof name === 'string' && name.trim()) || String(stageId);
  };

  const slots = useMemo(
    () => groupLiveAssignments(assignments, runnerLoad),
    [assignments, runnerLoad],
  );

  const cards = slots.map((slot) => ({
    slot,
    assignment: slot.current,
    task: slot.current ? taskById.get(String(slot.current.taskId)) || null : null,
    record: registry.get(slot.runnerId) || null,
  }));

  if (cards.length === 0) {
    return (
      <section
        aria-label="Runner tasks"
        data-testid="per-runner-tasks"
        className="h-full flex flex-col"
      >
        <div className="flex-1 flex flex-col items-center justify-center p-6 text-center text-slate-400 font-mono text-xs">
          <span className="text-3xl mb-2 opacity-40">💤</span>
          <p className="font-bold text-slate-300">Fleet idle — no live Runner assignments</p>
          <p className="text-[11px] mt-1">
            Deferred agent stages appear here when a Runner claims them.
          </p>
        </div>
      </section>
    );
  }

  if (compact) {
    return (
      <section
        aria-label="Runner tasks"
        data-testid="per-runner-tasks"
        className="flex flex-col gap-1"
      >
        {cards.map(({ slot, assignment: a, task }) => (
          <PerRunnerCompactRow
            key={slot.runnerId}
            assignment={a}
            slot={slot}
            task={task}
            nowMs={nowMs}
            stageName={stageName}
          />
        ))}
      </section>
    );
  }

  return (
    <section
      aria-label="Runner tasks"
      data-testid="per-runner-tasks"
      className="h-full flex flex-col gap-2 overflow-y-auto"
    >
      {cards.map(({ slot, assignment: a, task, record }) => (
        <PerRunnerCard
          key={slot.runnerId}
          assignment={a}
          slot={slot}
          task={task}
          record={record}
          nowMs={nowMs}
          stageName={stageName}
        />
      ))}
    </section>
  );
}

const PerRunnerCompactRow = ({ assignment: a, slot, task, nowMs, stageName }) => {
  const serving = a?.serving && typeof a.serving === 'object' ? a.serving : null;
  const extraCount = slot && slot.liveHoldCount > 1 ? slot.liveHoldCount - 1 : 0;
  return (
    <details
      data-testid={`per-runner-row-${a.runnerId}`}
